{{/*
Common ConfigMap data for next-search services
Usage: {{ include "common.config.elasticsearch" . }}
*/}}

{{- define "common.config.elasticsearch" -}}
{{- range $cluster, $config := .Values.config.elasticsearch }}
ELASTICSEARCH_{{ upper $cluster }}_HOST: "{{ $config.host }}"
ELASTICSEARCH_{{ upper $cluster }}_PORT: "{{ $config.port }}"
{{- with $config.connectTimeout }}
ELASTICSEARCH_{{ upper $cluster }}_CONNECT_TIMEOUT: "{{ . }}"
{{- end }}
{{- with $config.socketTimeout }}
ELASTICSEARCH_{{ upper $cluster }}_SOCKET_TIMEOUT: "{{ . }}"
{{- end }}
{{- with $config.catalogIndex }}
ELASTICSEARCH_{{ upper $cluster }}_CATALOG_INDEX: "{{ . }}"
{{- end }}
{{- with $config.productIndex }}
ELASTICSEARCH_{{ upper $cluster }}_PRODUCT_INDEX: "{{ . }}"
{{- end }}
{{- end }}
{{- end }}

{{- define "common.config.darae" -}}
DARAE_HOST: "{{ .Values.config.darae.host }}"
DARAE_PORT: "{{ .Values.config.darae.port }}"
{{- end }}

{{- define "common.config.valkey" -}}
REDIS_HOST: "{{ .Values.config.valkey.host }}"
REDIS_PORT: "{{ .Values.config.valkey.port }}"
REDIS_MAX_CONNECTIONS: "{{ .Values.config.valkey.maxConnections }}"
REDIS_CLUSTER_MODE: "{{ .Values.config.valkey.clusterMode }}"
{{- end }}

{{- define "common.config.mongodb" -}}
MONGODB_HOST: "{{ .Values.config.mongodb.host }}"
MONGODB_PORT: "{{ .Values.config.mongodb.port }}"
{{- end }}

{{/*
All common configs combined
*/}}
{{- define "common.config.all" -}}
{{- include "common.config.elasticsearch" . }}
{{- include "common.config.darae" . }}
{{- include "common.config.valkey" . }}
{{- include "common.config.mongodb" . }}
{{- end }}

{{- define "common.config.next" -}}
{{- include "common.config.elasticsearch" . }}
{{- include "common.config.darae" . }}
{{- include "common.config.valkey" . }}
{{- end }}

