apiVersion: v1
kind: ConfigMap
metadata:
  name: {{ include "dynamic-indexer.fullname" . }}-config
  labels:
    {{- include "dynamic-indexer.labels" . | nindent 4 }}
data:
  # Darae configuration
 {{- include "common.config.darae" . | nindent 2 }}

  # Valkey configuration
 {{- include "common.config.valkey" . | nindent 2 }}

  # Spring Boot profile
  SPRING_PROFILES_ACTIVE: {{ .Values.config.profile | quote }}

  # Elasticsearch configuration
  ELASTICSEARCH_URIS: {{ .Values.config.elasticsearch.backend.urls | quote }}
  # 추후에 나눠야함
  ELASTICSEARCH_BACKOFFICE_URIS: {{ .Values.config.elasticsearch.backoffice.urls | quote }}
  ELASTICSEARCH_FRONTEND_URIS: {{ .Values.config.elasticsearch.frontend.urls | quote }}
  ELASTICSEARCH_CONNECTION_TIMEOUT: {{ .Values.config.elasticsearch.connectionTimeout | quote }}
  ELASTICSEARCH_SOCKET_TIMEOUT: {{ .Values.config.elasticsearch.socketTimeout | quote }}

  KEYWORD_ANALYSIS_API_URL: {{ .Values.config.darae.host | quote }}
  KEYWORD_ANALYSIS_API_PORT: {{ .Values.config.darae.port | quote }}
  KEYWORD_ANALYSIS_API_USE_SSL: {{ .Values.config.darae.useSsl | quote }}

  VALKEY_GLOBAL_CACHE_HOSTS: {{ .Values.config.valkey.host | quote }}
  VALKEY_GLOBAL_CACHE_PASSWORD: {{ .Values.config.valkey.port | quote }}
  VALKEY_GLOBAL_CACHE_DATABASE: {{ .Values.config.valkey.database | quote }}

  #Kafka Configuration
  KAFKA_BOOTSTRAP_SERVERS: "{{ .Values.config.kafka.bootstrapServers }}"
  KAFKA_SCHEMA_REGISTRY_URL: "{{ .Values.config.kafka.schemaRegistryUrl }}"
  KAFKA_SASL_JAAS_CONFIG: "{{ .Values.config.kafka.saslJaasConfig }}"
  KAFKA_SASL_MECHANISM: "{{ .Values.config.kafka.saslMechanism }}"
  KAFKA_SECURITY_PROTOCOL: "{{ .Values.config.kafka.securityProtocol }}"

  # 1. Catalog CDC
  DYNAMIC_INDEXER_CATALOG_CDC_BOOTSTRAP_SERVERS: "{{ .Values.config.kafka.bootstrapServers }}"  #
  DYNAMIC_INDEXER_CATALOG_CDC_SCHEMA_REGISTRY_URL: "{{ .Values.config.kafka.schemaRegistryUrl }}"
  DYNAMIC_INDEXER_CATALOG_CDC_TOPIC: {{ .Values.config.dynamicIndexer.catalogCdc.topic | quote }}
  DYNAMIC_INDEXER_CATALOG_CDC_GROUP_ID: {{ .Values.config.dynamicIndexer.catalogCdc.groupId | quote }}
  DYNAMIC_INDEXER_CATALOG_CDC_CONCURRENCY: {{ .Values.config.dynamicIndexer.catalogCdc.concurrency | quote }}

  # Properties (이전에 추가한 부분)
  DYNAMIC_INDEXER_CATALOG_CDC_PROPERTIES_AUTO_OFFSET_RESET: {{ .Values.config.dynamicIndexer.catalogCdc.properties.autoOffsetReset | quote }}
  DYNAMIC_INDEXER_CATALOG_CDC_PROPERTIES_MAX_POLL_RECORDS: {{ .Values.config.dynamicIndexer.catalogCdc.properties.maxPollRecords | quote }}
  DYNAMIC_INDEXER_CATALOG_CDC_PROPERTIES_ENABLE_AUTO_COMMIT: {{ .Values.config.dynamicIndexer.catalogCdc.properties.enableAutoCommit | quote }}

  # 2. Product CDC
  DYNAMIC_INDEXER_PRODUCT_CDC_BOOTSTRAP_SERVERS: "{{ .Values.config.kafka.bootstrapServers }}"
  DYNAMIC_INDEXER_PRODUCT_CDC_SCHEMA_REGISTRY_URL: "{{ .Values.config.kafka.schemaRegistryUrl }}"
  DYNAMIC_INDEXER_PRODUCT_CDC_TOPIC: {{ .Values.config.dynamicIndexer.productCdc.topic | quote }}
  DYNAMIC_INDEXER_PRODUCT_CDC_GROUP_ID: {{ .Values.config.dynamicIndexer.productCdc.groupId | quote }}
  DYNAMIC_INDEXER_PRODUCT_CDC_CONCURRENCY: {{ .Values.config.dynamicIndexer.productCdc.concurrency | quote }}

  # Properties
  DYNAMIC_INDEXER_PRODUCT_CDC_PROPERTIES_AUTO_OFFSET_RESET: {{ .Values.config.dynamicIndexer.productCdc.properties.autoOffsetReset | quote }}
  DYNAMIC_INDEXER_PRODUCT_CDC_PROPERTIES_MAX_POLL_RECORDS: {{ .Values.config.dynamicIndexer.productCdc.properties.maxPollRecords | quote }}
  DYNAMIC_INDEXER_PRODUCT_CDC_PROPERTIES_ENABLE_AUTO_COMMIT: {{ .Values.config.dynamicIndexer.productCdc.properties.enableAutoCommit | quote }}

  # 3. Indexer Admin
  DYNAMIC_INDEXER_INDEXER_ADMIN_BOOTSTRAP_SERVERS: "{{ .Values.config.kafka.bootstrapServers }}"
  DYNAMIC_INDEXER_INDEXER_ADMIN_SCHEMA_REGISTRY_URL: "{{ .Values.config.kafka.schemaRegistryUrl }}"
  DYNAMIC_INDEXER_INDEXER_ADMIN_TOPIC: {{ .Values.config.dynamicIndexer.indexerAdmin.topic | quote }}
  DYNAMIC_INDEXER_INDEXER_ADMIN_GROUP_ID: {{ .Values.config.dynamicIndexer.indexerAdmin.groupId | quote }}
  DYNAMIC_INDEXER_INDEXER_ADMIN_CONCURRENCY: {{ .Values.config.dynamicIndexer.indexerAdmin.concurrency | quote }}

  # Properties
  DYNAMIC_INDEXER_INDEXER_ADMIN_PROPERTIES_AUTO_OFFSET_RESET: {{ .Values.config.dynamicIndexer.indexerAdmin.properties.autoOffsetReset | quote }}
  DYNAMIC_INDEXER_INDEXER_ADMIN_PROPERTIES_MAX_POLL_RECORDS: {{ .Values.config.dynamicIndexer.indexerAdmin.properties.maxPollRecords | quote }}
  DYNAMIC_INDEXER_INDEXER_ADMIN_PROPERTIES_ENABLE_AUTO_COMMIT: {{ .Values.config.dynamicIndexer.indexerAdmin.properties.enableAutoCommit | quote }}

